html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{% if letter_head and not no_letterhead %}
		<div class="letter-head">
			{{ letter_head }}
		</div>
	{% endif %}

	{% if print_heading_template %}
		{{ frappe.render_template(print_heading_template, {"doc": doc}) }}
	{% endif %}
{%- endmacro -%}

<style>
	@page {
		margin: 0.6in 0.4in 0.6in 0.4in;
	}

	.print-format {
		font-family: Georgia, serif;
		font-size: 10pt;
		color: #222;
	}

	.invoice-header {
		display: table;
		width: 100%;
		border-bottom: 3px double #1a4d7a;
		padding-bottom: 12px;
		margin-bottom: 16px;
	}

	.invoice-header-left,
	.invoice-header-right {
		display: table-cell;
		vertical-align: top;
	}

	.invoice-header-right {
		text-align: right;
	}

	.company-name {
		font-size: 20pt;
		font-weight: bold;
		color: #1a4d7a;
		letter-spacing: 1px;
	}

	.invoice-title {
		font-size: 14pt;
		color: #3a7abd;
		font-style: italic;
		margin-top: 2px;
	}

	.invoice-number {
		font-size: 18pt;
		font-weight: bold;
		color: #1a4d7a;
	}

	.invoice-status {
		color: #666;
		font-size: 9pt;
		margin-top: 3px;
	}

	.invoice-meta {
		width: 100%;
		margin-bottom: 16px;
		border-collapse: collapse;
	}

	.invoice-meta td {
		padding: 3px 8px;
		vertical-align: top;
	}

	.label-cell {
		width: 1%;
		color: #666;
		font-weight: bold;
		white-space: nowrap;
	}

	.value-cell {
		color: #222;
	}

	.section-title {
		font-size: 11pt;
		font-weight: bold;
		color: #1a4d7a;
		border-bottom: 1px solid #ccc;
		padding-bottom: 4px;
		margin: 20px 0 8px 0;
		text-transform: uppercase;
		letter-spacing: 0.5px;
	}

	.items-table {
		width: 100%;
		border-collapse: collapse;
		margin-bottom: 12px;
	}

	.items-table th {
		background: #1a4d7a;
		color: #fff;
		padding: 6px 8px;
		font-size: 9pt;
		text-align: left;
		font-weight: 600;
	}

	.items-table td {
		padding: 5px 8px;
		border-bottom: 1px solid #ddd;
		font-size: 9.5pt;
		vertical-align: top;
	}

	.items-table tr:nth-child(even) td {
		background: #f8faff;
	}

	.text-right {
		text-align: right;
	}

	.text-center {
		text-align: center;
	}

	.text-muted {
		color: #888;
		font-size: 8.5pt;
	}

	.totals-table {
		width: 320px;
		margin-left: auto;
		border-collapse: collapse;
		margin-top: 8px;
	}

	.totals-table td {
		padding: 4px 8px;
		font-size: 10pt;
		vertical-align: top;
	}

	.total-label {
		color: #666;
		white-space: nowrap;
	}

	.grand-total td {
		font-size: 12pt;
		font-weight: bold;
		color: #1a4d7a;
		border-top: 2px solid #1a4d7a;
		padding-top: 6px;
	}

	.outstanding td {
		font-weight: bold;
		color: #c0392b;
	}

	.ts-summary {
		background: #f0f5fe;
		border: 1px solid #d0dce8;
		border-radius: 4px;
		padding: 10px 14px;
		margin: 8px 0 16px 0;
		display: table;
		width: 100%;
	}

	.ts-summary .stat {
		display: table-cell;
		width: 33.33%;
		vertical-align: top;
	}

	.stat-label {
		font-size: 8.5pt;
		color: #666;
		text-transform: uppercase;
		letter-spacing: 0.3px;
	}

	.stat-value {
		font-size: 14pt;
		font-weight: bold;
		color: #1a4d7a;
		margin-top: 2px;
	}

	.terms-section {
		border-top: 1px solid #ddd;
		margin-top: 20px;
		padding-top: 10px;
		font-size: 9pt;
		color: #555;
	}

	.terms-title {
		font-weight: bold;
		margin-bottom: 4px;
		color: #333;
	}

	.cancelled-overlay {
		position: absolute;
		top: 0;
		left: 0;
		z-index: 0;
		width: 100%;
		height: 100%;
		display: flex;
		align-items: center;
		justify-content: center;
		pointer-events: none;
	}

	.cancelled-overlay h1 {
		color: rgba(200, 0, 0, 0.15);
		font-size: 80pt;
		transform: rotate(-30deg);
	}
</style>

<div {% if print_settings and print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
	{{ add_header(1, 1, doc, letter_head, no_letterhead, footer, print_settings) }}
</div>

{% if doc.status == "Cancelled" %}
	<div class="cancelled-overlay">
		<h1>{{ _("CANCELLED") }}</h1>
	</div>
{% endif %}

<div class="invoice-header">
	<div class="invoice-header-left">
		<div class="company-name">{{ doc.company or "" }}</div>
		<div class="invoice-title">{{ _("Timesheet Invoice") }}</div>
	</div>

	<div class="invoice-header-right">
		<div class="invoice-number">{{ doc.name }}</div>
		<div class="invoice-status">
			{{ _("Status") }}:
			<strong>{{ doc.status or "" }}</strong>
		</div>
	</div>
</div>

<table class="invoice-meta">
	<tr>
		<td class="label-cell">{{ _("Customer") }}:</td>
		<td class="value-cell" style="width: 30%;">
			<strong>{{ doc.customer_name or doc.customer or "" }}</strong>
		</td>

		<td class="label-cell">{{ _("Invoice Date") }}:</td>
		<td class="value-cell">
			{{ frappe.utils.format_date(doc.posting_date) if doc.posting_date else "" }}
		</td>
	</tr>

	<tr>
		<td class="label-cell">{{ _("PO No") }}:</td>
		<td class="value-cell">{{ doc.po_no or "" }}</td>

		<td class="label-cell">{{ _("Due Date") }}:</td>
		<td class="value-cell">
			{{ frappe.utils.format_date(doc.due_date) if doc.due_date else "" }}
		</td>
	</tr>

	<tr>
		<td class="label-cell">{{ _("Project") }}:</td>
		<td class="value-cell">{{ doc.project or "" }}</td>

		<td class="label-cell">{{ _("Currency") }}:</td>
		<td class="value-cell">{{ doc.currency or "" }}</td>
	</tr>
</table>

{% if doc.timesheets %}
	<div class="section-title">{{ _("Timesheet Details") }}</div>

	<table class="items-table">
		<thead>
			<tr>
				<th style="width: 5%;">#</th>
				<th style="width: 14%;">{{ _("Activity") }}</th>
				<th style="width: 12%;">{{ _("Project") }}</th>
				<th style="width: 14%;">{{ _("From") }}</th>
				<th style="width: 14%;">{{ _("To") }}</th>
				<th style="width: 8%;" class="text-right">{{ _("Hours") }}</th>
				<th style="width: 10%;" class="text-right">{{ _("Rate") }}</th>
				<th style="width: 13%;" class="text-right">{{ _("Amount") }}</th>
			</tr>
		</thead>

		<tbody>
			{% for ts in doc.timesheets %}
				{% set hourly_rate = (ts.billing_amount / ts.billing_hours) if ts.billing_hours else 0 %}

				<tr>
					<td class="text-muted">{{ ts.idx }}</td>
					<td>{{ ts.activity_type or "" }}</td>
					<td>{{ ts.project_name or ts.project or "" }}</td>
					<td>
						{{ frappe.utils.format_datetime(ts.from_time, "yyyy-MM-dd HH:mm") if ts.from_time else "" }}
					</td>
					<td>
						{{ frappe.utils.format_datetime(ts.to_time, "yyyy-MM-dd HH:mm") if ts.to_time else "" }}
					</td>
					<td class="text-right">
						{{ "%.2f"|format(ts.billing_hours or 0) }}
					</td>
					<td class="text-right">
						{{ frappe.utils.fmt_money(hourly_rate, currency=doc.currency) if hourly_rate else "" }}
					</td>
					<td class="text-right">
						{{ frappe.utils.fmt_money(ts.billing_amount or 0, currency=doc.currency) }}
					</td>
				</tr>
			{% endfor %}
		</tbody>
	</table>

	<div class="ts-summary">
		<div class="stat">
			<div class="stat-label">{{ _("Total Billable Hours") }}</div>
			<div class="stat-value">
				{{ "%.2f"|format(doc.total_billing_hours or 0) }}
			</div>
		</div>

		<div class="stat">
			<div class="stat-label">{{ _("Total Billing Amount") }}</div>
			<div class="stat-value">
				{{ frappe.utils.fmt_money(doc.total_billing_amount or 0, currency=doc.currency) }}
			</div>
		</div>

		<div class="stat">
			<div class="stat-label">{{ _("Timesheet Entries") }}</div>
			<div class="stat-value">
				{{ doc.timesheets | length }}
			</div>
		</div>
	</div>
{% endif %}

{% if doc.items %}
	<div class="section-title">{{ _("Invoice Items") }}</div>

	<table class="items-table">
		<thead>
			<tr>
				<th style="width: 5%;">#</th>
				<th>{{ _("Item") }}</th>
				<th style="width: 8%;" class="text-right">{{ _("Qty") }}</th>
				<th style="width: 8%;">{{ _("UOM") }}</th>
				<th style="width: 12%;" class="text-right">{{ _("Rate") }}</th>
				<th style="width: 12%;" class="text-right">{{ _("Amount") }}</th>
			</tr>
		</thead>

		<tbody>
			{% for item in doc.items %}
				<tr>
					<td class="text-muted">{{ item.idx }}</td>
					<td>
						{{ item.item_name or item.item_code or "" }}

						{% if item.description %}
							<br>
							<span class="text-muted">{{ item.description }}</span>
						{% endif %}
					</td>
					<td class="text-right">
						{{ "%.3f"|format(item.qty or 0) }}
					</td>
					<td>{{ item.uom or "" }}</td>
					<td class="text-right">
						{{ frappe.utils.fmt_money(item.rate or 0, currency=doc.currency) }}
					</td>
					<td class="text-right">
						{{ frappe.utils.fmt_money(item.amount or 0, currency=doc.currency) }}
					</td>
				</tr>
			{% endfor %}
		</tbody>
	</table>
{% endif %}

<table class="totals-table">
	{% if doc.discount_amount %}
		<tr>
			<td class="total-label">{{ _("Discount") }}:</td>
			<td class="text-right">
				-{{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}
			</td>
		</tr>
	{% endif %}

	{% if doc.taxes %}
		{% for tax in doc.taxes %}
			<tr>
				<td class="total-label">{{ tax.description or _("Tax") }}:</td>
				<td class="text-right">
					{{ frappe.utils.fmt_money(tax.tax_amount or 0, currency=doc.currency) }}
				</td>
			</tr>
		{% endfor %}
	{% endif %}

	<tr class="grand-total">
		<td>{{ _("Grand Total") }}:</td>
		<td class="text-right">
			{{ frappe.utils.fmt_money(doc.grand_total or 0, currency=doc.currency) }}
		</td>
	</tr>

	{% if doc.in_words %}
		<tr>
			<td class="total-label">{{ _("In Words") }}:</td>
			<td class="text-right" style="font-style: italic; color: #555; font-size: 9pt;">
				{{ doc.in_words }}
			</td>
		</tr>
	{% endif %}

	{% if doc.outstanding_amount %}
		<tr class="outstanding">
			<td>{{ _("Outstanding") }}:</td>
			<td class="text-right">
				{{ frappe.utils.fmt_money(doc.outstanding_amount, currency=doc.currency) }}
			</td>
		</tr>
	{% endif %}
</table>

{% if doc.terms %}
	<div class="terms-section">
		<div class="terms-title">{{ _("Terms and Conditions") }}</div>
		<div>{{ doc.terms }}</div>
	</div>
{% endif %}
